nodes.body:
Request example:

curl -X POST http://127.0.0.1:12121/v1/chat/completions \
-H "Content-Type: application/json" \
-H "Authorization: Bearer " \
-d '{
  "model": "glm-5.2",
  "messages": [
    {
      "role": "assistant",
      "content": " "
    }  
  ],
  "stream": false,
  "temperature": 1
}'

